mapper.select:
SELECT O.ITEM_NO AS itemNo , O.OPTION_NO AS optionNo , O.OPTION_NM AS optionNm , O.ITEM_PRICE AS itemPrice , I.ITEM_NM AS itemNm , I.SHIP_YN AS shipYn , I.SOLD_OUT_YN AS soldOutYn FROM ITEM_OPTION O INNER JOIN ITEMS I ON I.ITEM_NO = O.ITEM_NO WHERE O.ITEM_NO IN (
${order.itemNo}
) AND O.USE_YN = 'Y' AND O.DEL_YN = 'N' AND I.DEL_YN = 'N'
